/* ALLIM_MUSHAF_MOBILE_EXIT_V1_START */
.mushaf-mobile-nav { display: none; }
body.mushaf-view { --mushaf-return-height: calc(54px + env(safe-area-inset-top)); }
body.mushaf-view .mushaf-panel { padding-block-start: var(--mushaf-return-height); }
body.mushaf-view .mushaf-toolbar { position: relative; z-index: 10; }
body.mushaf-view .mushaf-mobile-nav {
  position: fixed;
  z-index: 79;
  inset: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  height: var(--mushaf-return-height);
  padding: calc(5px + env(safe-area-inset-top)) max(10px, env(safe-area-inset-right)) 5px max(10px, env(safe-area-inset-left));
  border-bottom: 1px solid var(--line);
  background: var(--surface, #fffef9);
}
body.mushaf-view .mushaf-exit-button,
body.mushaf-view .mushaf-home-button {
  display: inline-flex;
  min-height: 44px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 14px;
  border: 1px solid rgba(142,162,152,.72);
  border-radius: 14px;
  color: var(--forest);
  background: #fffef9;
  font: 800 12px/1.2 var(--sans);
  cursor: pointer;
  text-decoration: none;
}
body.mushaf-view .mushaf-home-button { width: 44px; flex: 0 0 44px; padding: 0; }
body.mushaf-view .mushaf-exit-button svg,
body.mushaf-view .mushaf-home-button svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.8; }
body.mushaf-view .mushaf-exit-button svg { transform: rotate(180deg); }
[dir="rtl"] body.mushaf-view .mushaf-exit-button svg { transform: none; }
body.mushaf-view .mushaf-exit-button:focus-visible,
body.mushaf-view .mushaf-home-button:focus-visible { outline: 3px solid var(--forest); outline-offset: 2px; }
body.mushaf-view .mushaf-exit-button:hover,
body.mushaf-view .mushaf-home-button:hover { background: var(--mint-2, #edf6f1); }
body.mushaf-view .ayah-wrap {
  height: calc(100dvh - var(--mushaf-return-height) - var(--mushaf-command-height) - var(--mushaf-dock-height));
}
body.mushaf-view .mushaf-page {
  width: min(820px, calc((100dvh - var(--mushaf-return-height) - var(--mushaf-command-height) - var(--mushaf-dock-height) - 8px) * .6667), calc(100vw - 8px));
}
/* ALLIM_MUSHAF_MOBILE_EXIT_V1_END */

function:
function exitMushafToReading(restoreFocus) {
    clearAutoAdvance();
    stopRecognitionImmediately();
    document.body.classList.remove("audio-view");
    setMushafMode(false);
    stopVerseAudio(false);
    var audioPanel = document.getElementById("audio-panel");
    if (audioPanel) audioPanel.hidden = true;
    setStudioMode(false);
    selectReaderMode("read");
    setMeaningVisibility(state.showMeaning);
    if (restoreFocus) {
      window.requestAnimationFrame(function () {
        var readerControl = document.getElementById("open-quran-search");
        if (readerControl) readerControl.focus();
      });
    }
  }

